import React, { useEffect, useState } from "react";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button,  } from "@heroui/react";
import { ToastContainer, toast } from "react-toastify";
import { getLoggedInUser } from "../../helpers/authUtils";
import useApi from "../../hooks/useApi";
import kycDocumentsApi from "../../api/users/kycDocumentsApi";



export default function ViewDocumentModal({ openModal, setopenModal, item, updated, setUpdated, modalTitle, selectedDocument }) {

    const [user, setUser] = useState()

    useEffect(() => {
      setUser(getLoggedInUser());
    }, []);

    console.log("selectedDocument", selectedDocument);

    const [errors, setErrors] = useState();

    useEffect(() => {
      setUser(getLoggedInUser());
    }, []);

    const documentsActionsApi = useApi(kycDocumentsApi.kycDocumentsAction);

    const handleDeleteDocument = async (doc) => {
      const result = await documentsActionsApi.request({
        action: "DeleteDocument",
        document_id: doc.id,
      });

      if (result.ok) {
        setopenModal(false);
      } else {
        console.log("res", result.data);
      }
    };
    const handleVerifyDocument = async (doc) => {
      console.log("am here");
      const result = await documentsActionsApi.request({
        action: "VerifyDocument",
        document_id: doc.id,
      });

      if (result.ok) {
        setopenModal(false);

        console.log("result", result);
      } else {
        setErrors(result.data.errors);
        console.log("res", result.data);
      }
    };

    useEffect(() => {
      if (errors && errors.length) {
        errors.map((x) => {
          return toast.error(x);
        });
      }
    }, [errors]);
    return (
      <>
        <Modal
          isOpen={openModal}
          placement="top"
          size="lg"
          onClose={() => setopenModal(false)}
        >
          <ModalContent>
            <ToastContainer position="bottom-center" theme="colored" />
            <ModalHeader className="flex flex-col gap-1 items-center">
              KYC Document Details
            </ModalHeader>
            <ModalBody>
              <img
                src={selectedDocument.document}
                className="h-1/4 w-full"
                alt=""
              />

              <p className="font-bold">
                Document #: {selectedDocument.document_number}
              </p>
              <p>TYPE: {selectedDocument.document_type}</p>
              <p
                className="uppercase
                        "
              >
                IS VERIFIED: {selectedDocument.is_verified}
              </p>
            </ModalBody>
            <ModalFooter>
              {selectedDocument.is_verified === "false" && (
                <Button
                  color="danger"
                  variant="light"
                  onPress={() => handleDeleteDocument(selectedDocument)}
                >
                  Delete
                </Button>
              )}
              {user &&
                user.is_staff === "true" &&
                selectedDocument.is_verified === "false" && (
                  <Button
                    color="primary"
                    onPress={() => handleVerifyDocument(selectedDocument)}
                  >
                    Verify
                  </Button>
                )}
            </ModalFooter>
          </ModalContent>
        </Modal>
      </>
    );
}
